class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0
        for i, char in enumerate(s):
            position_in_string = i + 1
            reversed_alphabet_index = ord('z') - ord(char) + 1
            total += position_in_string * reversed_alphabet_index
        return total
