class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        ops = 0
        while True:
            # Check if array is already non-decreasing
            non_decreasing = True
            for i in range(len(nums) - 1):
                if nums[i] > nums[i + 1]:
                    non_decreasing = False
                    break
            if non_decreasing:
                return ops

            # Find adjacent pair with minimum sum (leftmost if tie)
            min_sum = float('inf')
            min_idx = -1
            for i in range(len(nums) - 1):
                s = nums[i] + nums[i + 1]
                if s < min_sum:
                    min_sum = s
                    min_idx = i

            # Replace the pair with their sum
            nums = nums[:min_idx] + [min_sum] + nums[min_idx + 2:]
            ops += 1
