            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        union(u, v)

    # Count connected components
    comps = 0
    for i in range(1, n + 1):
        if find(i) == i:
            comps += 1

    ans = m - n + comps
    print(ans)

