from typing import List

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        # Map each value to the sorted list of indices where it appears.
        pos = {}
        for i, v in enumerate(nums):
            pos.setdefault(v, []).append(i)

        # For each index, store its rank within its value's position list.
        rank = [0] * n
        for v, lst in pos.items():
            for k, idx in enumerate(lst):
                rank[idx] = k

        def circ_dist(i: int, j: int) -> int:
            d = abs(i - j)
            return min(d, n - d)

        ans = []
        for q in queries:
            v = nums[q]
            lst = pos[v]
            m = len(lst)
            if m == 1:
                ans.append(-1)
            else:
                p = rank[q]
                prev_idx = lst[(p - 1) % m]
                next_idx = lst[(p + 1) % m]
                best = min(circ_dist(q, prev_idx), circ_dist(q, next_idx))
                ans.append(best)
        return ans
