class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # Collect all distinct positive numbers
        distinct_positives = set()
        for num in nums:
            if num > 0:
                distinct_positives.add(num)

        # If there is at least one positive number, sum them all
        if distinct_positives:
            return sum(distinct_positives)
        # Otherwise all numbers are <= 0; we must pick at least one element,
        // so choose the largest (least negative or zero)
        return max(nums)
